# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use a safety-first finite-state controller with target confirmation,
    hysteretic steering, and bounded reacquisition memory.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    age = int(observation["track_age"])
    lost = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    closing = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    if safety < 0.60 or closing >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = visible and target_conf >= 0.55 and identity_conf >= 0.60
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost > 0:
            if lost <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            action = scan
            memory["scan_direction"] = (
                "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
            )
            return emit(action, 0.75, "SEARCH")
        return emit(scan, 0.75, "SEARCH")

    if age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    heading_error = abs(float(observation["heading_error"]))
    if distance == "near":
        if heading_error <= 15.0 and identity_conf >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        action = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        return emit(action, 0.88, "APPROACH")

    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    # Keep an established turn through a small noisy bearing reversal.
    if last_action == "VEER_LEFT" and left and bearing < 8.0:
        return emit("VEER_LEFT", 0.86, "APPROACH")
    if last_action == "VEER_RIGHT" and right and bearing > -8.0:
        return emit("VEER_RIGHT", 0.86, "APPROACH")

    if bearing < -15.0 and left:
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if bearing > 15.0 and right:
        return emit("VEER_RIGHT", 0.90, "APPROACH")
    if center:
        return emit("FORWARD", 0.90, "APPROACH")
    if left:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if right:
        return emit("VEER_RIGHT", 0.82, "APPROACH")
    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
